std::mutex m;
std::condition_variable cv;
bool ready = false;

void wait_for_ready() {
    std::unique_lock<std::mutex> lock(m);
    cv.wait(lock, [] { return ready; });   // releases while waiting, relocks after
}                                           // lock released at scope exit

void transfer(Account& from, Account& to, int cents) {
    std::scoped_lock lock(from.m, to.m);   // both, deadlock-avoiding
    from.balance -= cents;
    to.balance   += cents;
}                                           // both released here
